// Legacy GEO interface of mrdoob/slop-newyork (the engine's geodata module), now backed by Ede.
// Everything Manhattan-specific is empty; the mapped OSM city lives in GEO.ede (the irregular-city data path
// of the engine, see ede-geometry.js) and is generated by tools/build-ede-geodata.mjs.
import { EDE_DATA } from './ede-geodata.js';

const [minX, minZ, maxX, maxZ] = EDE_DATA.meta.bounds;

export const GEO = {
  version: 2,
  city: 'Ede',
  cityName: 'Ede',
  frame: { bearingDeg: 0, origin: 'Oude Kerk', units: 'm', cutZ: minZ, strip: 20, sidewalk: 3 },
  manhattan: [minX, minZ, maxX, minZ, maxX, maxZ, minX, maxZ],
  upperManhattan: [],
  streets: [],
  avenues: [],
  broadway: [],
  piers: [],
  islands: {},
  boroughs: { newJersey: [], brooklyn: [], queens: [], bronx: [], statenIsland: [] },
  bridges: {},
  points: {},
  plazas: [],
  centralPark: { bounds: { minX, maxX, minZ, maxZ }, lawns: [], water: EDE_DATA.water, drives: [] },
  parks: EDE_DATA.parks.map((p) => ({ name: p.name, kind: p.kind, rings: [p.ring], holes: p.holes })),
  landmarks: EDE_DATA.landmarks,
  roads: [],
  blocks: [],
  roadGraph: EDE_DATA.roadGraph,
  ede: EDE_DATA
};
